def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'required destination'
    req = nb.get('required_transform') or 'required transform'
    if not target or not req:
        return None
    if stage == 'wrong_transform':
        return {'message': 'The carried object is not the requested target. Do not transform it; recover by setting it aside only if needed, then find a ' + req + ' ' + target + '.'}
    if stage == 'transform' and nb.get('target_type') and not nb.get('transformed'):
        return {'message': 'Carry the ' + target + ' to a place that can ' + req + ' it, then keep carrying it to the ' + dest + '; do not use other appliance types.'}
    if stage == 'wrong_inventory' or stage == 'find_target':
        return {'message': 'Do not carry or transform a non-target. Find and take a ' + target + ', then ' + req + ' it before placing it.'}
    if stage == 'go_destination' and not nb.get('destination_hinted'):
        nb['destination_hinted'] = True
        return {'message': 'The ' + target + ' has already been ' + req + 'ed. Carry it to a ' + dest + ' and put it there; avoid extra transforms or wrong receptacles.'}
    return None
